#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
Fix: build falhou --
'getColor' in 'Context' is final and cannot be overridden
'getColorStateList' in 'Context' is final and cannot be overridden

Causa raiz: o fix anterior (fix_display_and_color_apply.py) tentou
sobrescrever Context.getColor(int) e Context.getColorStateList(int)
dentro de XaulinXsThemedContextWrapper para resolver "cor nao aplicava
em lugar nenhum". Mas esses dois metodos sao declarados `final` na
propria classe Context do Android SDK -- nao e possivel sobrescreve-los
em NENHUMA subclasse (nem ContextWrapper, nem Activity). O codigo
chegou a ser escrito mas nunca poderia compilar.

Fix: remove esses dois overrides impossiveis. O ContextWrapper volta a
sobrescrever so getResources() (cobertura parcial, mas real, e que
compila) -- cobrindo quem chama resources.getColor(id) diretamente.
O caminho via context.getColor(id) (mais comum no codigo real do
Launcher3) fica sem cobertura por enquanto: cobertura completa exigiria
um Runtime Resource Overlay via aapt2, pausado por decisao do usuario
(sem root, o Launcher3 nao consegue executar o aapt2 que mora no
sandbox do Termux).

Rode este script na RAIZ do checkout local do repo (mesmo diretorio do
gradlew), dentro do Termux.

python3 fix_build_final_getcolor.py

Idempotente.
"""
import base64
import sys
from pathlib import Path

def die(msg):
    print("ERRO:", msg)
    sys.exit(1)

if not Path("gradlew").exists():
    die("rode este script na raiz do checkout (onde esta o gradlew).")

TARGET = "modules/customizations/src/com/xaulinxs/customizations/theme/XaulinXsThemeColorResources.kt"
NEW_B64 = ''
MARKER = 'cobertura PARCIAL'

target = Path(TARGET)
if not target.exists():
    die(f"nao encontrei {TARGET}. Voce ja rodou os scripts anteriores (apply_custom_colors.py etc.)?")

new_content = base64.b64decode(NEW_B64).decode("utf-8")
current_content = target.read_text(encoding="utf-8")

if MARKER in current_content:
    print("Ja corrigido -- nada a fazer.")
else:
    target.write_text(new_content, encoding="utf-8")
    print(f"OK: corrigido {TARGET}.")
    print("Agora: git add -A && git commit -m 'fix: remove override impossivel de Context.getColor (final no Android)' && git push")
    print("Depois: ./gradlew assembleNoQuickstepDebug")
